    (function(){const key='pf.projectView';const apply=function(view){if(view!=='list'){view='kanban';}$('[data-pf-view]').each(function(){const on=$(this).data('pfView')===view;$(this).toggleClass('active',on).attr('aria-pressed',on?'true':'false');});$('[data-pf-view-pane]').each(function(){$(this).toggleClass('d-none',$(this).data('pfViewPane')!==view);});};let saved='kanban';try{saved=window.localStorage.getItem(key)||'kanban';}catch(e){}apply(saved);$(document).on('click','[data-pf-view]',function(){const view=$(this).data('pfView');apply(view);try{window.localStorage.setItem(key,view);}catch(e){}});})();

