    (function(){const $m=$('#pf-contract-viewer');if(!$m.length)return;let contracts=[];try{contracts=JSON.parse(String($m.attr('data-contracts')||'[]'));}catch(e){contracts=[];}
      const libBase=String($m.data('lib-base')||''),$stage=$m.find('[data-pf-cv-stage]'),$tabs=$m.find('[data-pf-cv-tabs]');let current=null;
      const esc=v=>$('<div>').text(String(v??'')).html();
      const loaders={};const loadLib=(file,globalName)=>{if(window[globalName])return Promise.resolve(window[globalName]);if(!loaders[file])loaders[file]=new Promise((res,rej)=>{const s=document.createElement('script');s.src=`${libBase}/${file}`;s.onload=()=>window[globalName]?res(window[globalName]):rej(new Error('lib'));s.onerror=()=>rej(new Error('lib'));document.head.appendChild(s);});return loaders[file];};
      const busyStage=()=>$stage.html('<div class="pf-cv-msg"><span class="spinner-border spinner-border-sm"></span> Carregando o arquivo...</div>');
      const message=(icon,title,text,extra='')=>$stage.html(`<div class="pf-cv-msg"><i class="ti ${icon}"></i><strong>${esc(title)}</strong><span>${esc(text)}</span>${extra}</div>`);
      const frameHtml=(html,css='')=>{const doc=`<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;margin:0;padding:28px 36px;color:#1f2937;line-height:1.55;background:#fff}img{max-width:100%}table{border-collapse:collapse}td,th{border:1px solid #d9dee6;padding:4px 8px;font-size:13px;vertical-align:top}${css}</style></head><body>${html}</body></html>`;const f=document.createElement('iframe');f.className='pf-cv-frame';f.setAttribute('sandbox','');f.srcdoc=doc;$stage.empty().append(f);};
      const fetchBuf=url=>fetch(url,{credentials:'same-origin'}).then(r=>{if(!r.ok)throw new Error(String(r.status));return r.arrayBuffer();});
      const kind=d=>{const e=String(d.ext||'').toLowerCase(),m=String(d.mime||'').toLowerCase();if(e==='pdf'||m==='application/pdf')return'pdf';if(m.startsWith('image/')||['png','jpg','jpeg','gif','webp','bmp','svg'].includes(e))return'image';if(['docx'].includes(e))return'docx';if(['xlsx','xlsm','xls','ods','csv'].includes(e))return'sheet';if(m.startsWith('video/')||['mp4','webm','ogg'].includes(e))return'video';if(m.startsWith('audio/')||['mp3','wav','m4a'].includes(e))return'audio';if(m.startsWith('text/')||['txt','log','md','json','xml','html','htm','ini','conf','yml','yaml'].includes(e))return'text';return'other';};
      const show=d=>{current=d;$tabs.find('[data-doc]').each(function(){$(this).toggleClass('is-active',Number($(this).data('doc'))===d.id&&Number($(this).data('contract'))===d.contract.id);});
        const c=d.contract;$m.find('[data-pf-cv-title]').text(c.name);$m.find('[data-pf-cv-sub]').text([c.number?`Nº ${c.number}`:'',c.begin_date?`Início ${String(c.begin_date).slice(0,10).split('-').reverse().join('/')}`:'',d.filename||''].filter(Boolean).join(' · '));$m.find('[data-pf-cv-glpi]').attr('href',c.url);
        const $nt=$m.find('[data-pf-cv-newtab]');if(d.id){$nt.removeClass('d-none').attr('href',d.view_url);}else{$nt.addClass('d-none');}
        if(!d.id){message('ti-file-off','Este contrato não tem arquivo anexado','Anexe o PDF (ou outro arquivo) na aba Documentos do contrato no GLPI para vê-lo aqui.',`<a class="btn btn-outline-primary btn-sm mt-2" href="${esc(c.documents_url)}" target="_blank" rel="noopener"><i class="ti ti-paperclip"></i> Anexar no contrato</a>`);return;}
        if(!d.has_file){if(d.link){message('ti-link','Documento externo',d.link,`<a class="btn btn-outline-primary btn-sm mt-2" href="${esc(d.link)}" target="_blank" rel="noopener noreferrer"><i class="ti ti-external-link"></i> Abrir link</a>`);}else{message('ti-file-off','Documento sem arquivo','O documento vinculado ao contrato não tem arquivo.');}return;}
        const k=kind(d);busyStage();
        if(k==='pdf'){const f=document.createElement('iframe');f.className='pf-cv-frame';f.src=d.view_url+'#view=FitH';f.title=d.name;$stage.empty().append(f);return;}
        if(k==='image'){$stage.html(`<div class="pf-cv-image"><img src="${esc(d.view_url)}&img=1" alt="${esc(d.name)}"></div>`);return;}
        if(k==='video'){$stage.html(`<div class="pf-cv-image"><video src="${esc(d.view_url)}" controls></video></div>`);return;}
        if(k==='audio'){$stage.html(`<div class="pf-cv-msg"><i class="ti ti-music"></i><strong>${esc(d.name)}</strong><audio src="${esc(d.view_url)}" controls></audio></div>`);return;}
        if(k==='text'){fetch(d.view_url,{credentials:'same-origin'}).then(r=>{if(!r.ok)throw new Error();return r.text();}).then(txt=>$stage.html(`<pre class="pf-cv-text">${esc(txt)}</pre>`)).catch(()=>message('ti-alert-triangle','Não foi possível abrir o arquivo','Tente "Abrir em nova aba".'));return;}
        if(k==='docx'){Promise.all([loadLib('mammoth.browser.min.js','mammoth'),fetchBuf(d.view_url)]).then(([mm,buf])=>mm.convertToHtml({arrayBuffer:buf})).then(r=>frameHtml(r.value||'<p>(documento vazio)</p>','body{max-width:900px;margin:0 auto}')).catch(()=>message('ti-alert-triangle','Não foi possível exibir o documento','Tente "Abrir em nova aba".'));return;}
        if(k==='sheet'){Promise.all([loadLib('xlsx.full.min.js','XLSX'),fetchBuf(d.view_url)]).then(([X,buf])=>{const wb=X.read(buf,{type:'array'});const parts=wb.SheetNames.map((n,i)=>`<h3 style="margin:${i?'28px':'0'} 0 10px;font-size:15px">${esc(n)}</h3>`+X.utils.sheet_to_html(wb.Sheets[n],{header:'',footer:''}));frameHtml(parts.join(''),'body{padding:20px}table{min-width:60%}tr:nth-child(even) td{background:#f8fafc}');}).catch(()=>message('ti-alert-triangle','Não foi possível exibir a planilha','Tente "Abrir em nova aba".'));return;}
        message('ti-file-unknown',`Pré-visualização indisponível para .${d.ext||'?'}`,'Este tipo de arquivo não pode ser exibido no navegador. Use "Abrir em nova aba" para abrir com o aplicativo do seu computador.');};
      const docs=[];contracts.forEach(c=>{(c.documents&&c.documents.length?c.documents:[{id:0}]).forEach(d=>docs.push({...d,contract:c}));});
      if(docs.length>1){$tabs.removeClass('d-none').html(docs.map(d=>`<button type="button" data-doc="${d.id}" data-contract="${d.contract.id}"><i class="ti ti-${d.id?'file-text':'file-off'}"></i><span>${esc(contracts.length>1?`${d.contract.name} · `:'')}${esc(d.id?d.name:'Sem arquivo')}</span></button>`).join(''));$tabs.on('click','[data-doc]',function(){const id=Number($(this).data('doc')),cid=Number($(this).data('contract'));const d=docs.find(x=>x.id===id&&x.contract.id===cid);if(d)show(d);});}
      $m.on('shown.bs.modal',function(){if(!current&&docs.length)show(docs[0]);});
      $m.find('[data-pf-cv-unlink]').on('click',function(){if(!current)return;const c=current.contract;if(!confirm(`Desvincular o contrato "${c.name}" deste projeto? Depois você pode vincular outro.`))return;const $b=$(this);busy($b,true);api(projectEndpoint,{action:'contract_unlink',project_id:projectId,relation_id:c.relation_id,_glpi_csrf_token:csrf}).done(r=>r?.ok?window.location.reload():toast(r?.message||'Falha ao desvincular contrato.','error')).fail(x=>toast(x.responseJSON?.message||'Falha ao desvincular contrato.','error')).always(()=>busy($b,false));});
    })();
